def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each nonzero cell in the top row is a vertical ray's color and column.
    seeds = {}
    for c, color in enumerate(grid[0]):
        if color:
            seeds[color] = c

    # Edge markers connect horizontally to the top-row seed of the same color.
    marker_rows = {}
    for r in range(1, h):
        for c in (0, w - 1):
            color = grid[r][c]
            if color in seeds:
                marker_rows.setdefault(color, []).append(r)
                target = seeds[color]
                for cc in range(min(c, target), max(c, target) + 1):
                    out[r][cc] = color

    # Extend each top-row seed downward, stopping at its matching edge marker
    # if one exists; otherwise it reaches the bottom.
    for color, c in seeds.items():
        end = min(marker_rows[color]) if color in marker_rows else h - 1
        for r in range(end + 1):
            out[r][c] = color

    return out
